const sections={discover:{title:'Start with the look you saved.',description:'Choose a garment in a screenshot, describe what matters, and explore similar pieces. The current prototype separates sample matches from live provider-backed results.',tag:'Image-first discovery',image:'assets/outfit.jpg',alt:'Generated outfit reference'},mall:{title:'Explore products with context.',description:'Browse the existing brand and product discovery experience. Store and product information is shown with the available source details; availability and delivery are not guaranteed.',tag:'Product discovery',image:'assets/cream.jpg',alt:'Generated cream shirt'},community:{title:'Ask for a lead. Share why it fits.',description:'The Community flow supports “find this” questions and product leads. Shared posts require the configured database service; the app does not claim that a lead is visually verified.',tag:'Community questions',image:'assets/outfit.jpg',alt:'Generated outfit reference'},profile:{title:'Keep your style close.',description:'The existing profile and account setup flow stays part of the product. Personal wardrobe edits in the local walkthrough are stored in browser storage.',tag:'Profile & preferences',image:'assets/cream.jpg',alt:'Generated cream shirt'}};
    const tabs=[...document.querySelectorAll('[role=tab]')];const panel=document.querySelector('#panel');
    function activate(tab,focus=false){const id=tab.dataset.tab;const item=sections[id];tabs.forEach(t=>{const active=t===tab;t.setAttribute('aria-selected',String(active));t.tabIndex=active?0:-1});panel.setAttribute('aria-labelledby',tab.id);document.querySelector('#panel-kicker').textContent=`0${tabs.indexOf(tab)+1} · ${tab.textContent}`;document.querySelector('#panel-title').textContent=item.title;document.querySelector('#panel-description').textContent=item.description;document.querySelector('#panel-tag').textContent=item.tag;const image=document.querySelector('#panel-image');image.src=item.image;image.alt=item.alt;if(focus)tab.focus()}
    tabs.forEach(tab=>tab.addEventListener('click',()=>activate(tab)));document.querySelector('[role=tablist]').addEventListener('keydown',event=>{const i=tabs.indexOf(document.activeElement);if(i<0)return;let next=null;if(event.key==='ArrowRight')next=tabs[(i+1)%tabs.length];if(event.key==='ArrowLeft')next=tabs[(i-1+tabs.length)%tabs.length];if(event.key==='Home')next=tabs[0];if(event.key==='End')next=tabs[tabs.length-1];if(next){event.preventDefault();activate(next,true)}});
